script:
if (-not $USERNAME) { throw 'USERNAME is required' }
Import-Module ActiveDirectory -ErrorAction Ignore
$existing = Get-ADUser -Filter "SamAccountName -eq '$USERNAME'" -ErrorAction Ignore
if ($existing) {
    $u = @{}
    if ($FULLNAME) { $u.DisplayName = $FULLNAME }
    if ($DESCRIPTION) { $u.Description = $DESCRIPTION }
    if ($u.Count) { Set-ADUser -Identity $USERNAME @u }
} else {
    $params = @{ Name = $USERNAME; SamAccountName = $USERNAME; Enabled = $true; PasswordNotRequired = $true }
    if ($FULLNAME) { $params.DisplayName = $FULLNAME }
    if ($DESCRIPTION) { $params.Description = $DESCRIPTION }
    if ($NEVER_EXPIRES -eq '1') { $params.PasswordNeverExpires = $true }
    New-ADUser @params | Out-Null
}
Set-ADAccountControl -Identity $USERNAME -PasswordNotRequired $true
if ($NEVER_EXPIRES -eq '1') { Set-ADUser -Identity $USERNAME -PasswordNeverExpires $true }
Set-ADUser -Identity $USERNAME -Enabled $true
